import sys
from collections import deque


def main():
    data = map(int, sys.stdin.buffer.read().split())
    try:
        n = next(data)
        m = next(data)
    except StopIteration:
        return

    adjacency = [[] for _ in range(n)]
    factory_present = bytearray(n)
    weights = []

    for _ in range(m):
        airport = next(data) - 1
        factory = next(data) - 1
        days = next(data)
        adjacency[airport].append((days, factory))
        factory_present[factory] = 1
        weights.append(days)

    if m < n or not all(factory_present) or any(not row for row in adjacency):
        print(-1)
        return

    for row in adjacency:
        row.sort()

    weights = sorted(set(weights))
    sys.setrecursionlimit(max(1000, 2 * n + 100))

    def feasible(limit):
        airport_match = [-1] * n
        factory_match = [-1] * n
        distance = [0] * n
        matched = 0
        infinity = n + 1

        while matched < n:
            queue = deque()
            for airport in range(n):
                if airport_match[airport] == -1:
                    distance[airport] = 0
                    queue.append(airport)
                else:
                    distance[airport] = infinity

            shortest = infinity
            while queue:
                airport = queue.popleft()
                next_distance = distance[airport] + 1
                if next_distance > shortest:
                    continue

                for days, factory in adjacency[airport]:
                    if days > limit:
                        break
                    partner = factory_match[factory]
                    if partner == -1:
                        shortest = next_distance
                    elif next_distance < shortest and distance[partner] == infinity:
                        distance[partner] = next_distance
                        queue.append(partner)

            if shortest == infinity:
                return False

            cursor = [0] * n

            def augment(airport):
                row = adjacency[airport]
                next_distance = distance[airport] + 1

                while cursor[airport] < len(row):
                    days, factory = row[cursor[airport]]
                    if days > limit:
                        break
                    cursor[airport] += 1
                    partner = factory_match[factory]

                    if partner == -1:
                        if next_distance != shortest:
                            continue
                    elif distance[partner] != next_distance or not augment(partner):
                        continue

                    airport_match[airport] = factory
                    factory_match[factory] = airport
                    return True

                distance[airport] = infinity
                return False

            for airport in range(n):
                if airport_match[airport] == -1 and augment(airport):
                    matched += 1

        return True

    if not feasible(weights[-1]):
        print(-1)
        return

    left = 0
    right = len(weights) - 1
    while left < right:
        middle = (left + right) // 2
        if feasible(weights[middle]):
            right = middle
        else:
            left = middle + 1

    print(weights[left])


if __name__ == "__main__":
    main()
